mapper.select:
select DISTINCT a.device_code, b.iot_device_id, ( case when length(IFNULL(ten.device_name, '')) = 0 then b.device_name else ten.device_name end ) device_name, b.device_status, b.province_id, b.city_id, b.county_id, c.area_name as provinceName, c.area_parent_code as provinceParentId, d.area_name as cityName, d.area_parent_code as cityParentId, e.area_name as countyName, e.area_parent_code as countyParentId from vm_order_sensor_devices a left join vm_iot_device_t b on b.device_code = a.device_code and b.category_code = 2 left join sys_area c on b.province_id = c.area_code left join sys_area d on b.city_id = d.area_code left join sys_area e on b.county_id = e.area_code LEFT JOIN vm_tenant_iot_device_rel_t ten on ten.device_code = a.device_code and ten.tenant_id = a.tenant_id and ten.industry_code=a.industry_code and ten.delete_flag='0' where a.delete_flag = 0 and b.delete_flag = 0 and a.ord_status in (0,1,2) and a.category_code=2 and b.province_id is not null and b.city_id is not null and b.county_id is not null
and a.tenant_id = #{tenantId}
and b.device_type = #{deviceType}
and b.device_type in
#{item}
${dataScope} ORDER BY province_id,city_id,county_id,device_code

select distinct t1.device_code, ms.monitor_code as factorCode, ( case when length(IFNULL(mc.monitor_name, '')) = 0 then ms.monitor_desc else mc.monitor_name end ) factorName, ms.monitor_code as factorId from vm_order_sensor_devices t1 INNER JOIN vm_sensor_monitor_status ms on t1.device_code=ms.device_code LEFT JOIN vm_sensor_monitor_config mc on ms.monitor_code=mc.monitor_code where t1.delete_flag = 0 and ms.delete_flag = 0 and mc.delete_flag = 0 and t1.category_code = 2 and t1.ord_status in (0, 1, 2)
and t1.tenant_id = #{tenantId}
${dataScope} group by ms.monitor_code

SELECT device_code,factorCode,sensorType,sensorTypeName,factorName,factorId,monitorUnits FROM( select distinct t1.device_code, ms.monitor_code as factorCode, IFNULL(ty.type_code,'') as sensorType, IFNULL(ty.type_name,'') as sensorTypeName, ( case when length(IFNULL(mc.monitor_name, '')) = 0 then ms.monitor_desc else mc.monitor_name end ) factorName, ms.monitor_code as factorId, mc.monitor_units as monitorUnits from vm_order_sensor_devices t1 INNER JOIN vm_sensor_monitor_status ms on t1.device_code=ms.device_code LEFT JOIN vm_sensor_device_type ty on ty.type_code = ms.sensor_code and ty.delete_flag ='0' LEFT JOIN vm_sensor_monitor_config mc on ms.monitor_code=mc.monitor_code where t1.delete_flag = 0 and ms.delete_flag = 0 and mc.delete_flag = 0 and t1.ord_status in (0, 1, 2) and t1.tenant_id = #{tenantId} and t1.device_code in
#{deviceCode}
ORDER BY ty.type_code desc)a GROUP BY a.factorCode

select id
from vm_iot_alarm_groups_t
where iot_config_id = #{id}

