mapper.select:
SELECT f.factor_code AS factorCode, f.factor_name AS factorName, f.min_char AS minChar, f.min_num AS minNUm, f.max_char AS maxChar, f.max_num AS maxNum FROM vm_iot_alarm_config_t t LEFT JOIN vm_iot_alarm_factor_t f ON f.group_id = t.id WHERE t.config_status = '1' AND t.delete_flag = 0 AND f.delete_flag = 0
AND t.tenant_id = #{param.tenantId}
AND t.industry_code = #{param.industryCode}

select id,groups_name,device_type,iot_config_id,anti_shake_type,anti_shake_num,anti_shake_time,anti_shake_time_unit,relation FROM vm_iot_alarm_groups_t WHERE delete_flag = 0
AND iot_config_id IN
#{configId}

SELECT group_id AS groupId, device_code AS deviceCode FROM vm_iot_alarm_device_t WHERE delete_flag = 0
AND group_id IN
#{groupId}

SELECT group_id AS groupId, factor_code AS factorCode, factor_name AS factorName, min_char AS minChar, min_num AS minNum, max_char AS maxChar, max_num AS maxnum, value_type AS valueType, sum_value AS sumValue, sum_value_unit AS sumValueUnit, monitor_units AS monitorUnits FROM vm_iot_alarm_factor_t WHERE delete_flag = 0
AND group_id IN
#{groupId}
